const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const pay_button = require('button')
const invoice_input = require('input_field')
const pay_invoice_confirmation = require('pay_invoice_confirmation')

module.exports = pay_invoice

async function pay_invoice(opts = {}, callbacks = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const onDecode = callbacks.onDecode || null
  const onPay = callbacks.onPay || null
  const onCloseFn = callbacks.onClose || null

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
    <div class="pay-invoice-container">
      <div class="pay-invoice-header">  
        <div class="title-container"> 
          <div class="header-title">Pay Lightning Invoice</div>
          <div class="lightning-icon"></div>
        </div>  
        <div class="x-icon"></div>
      </div>
      <div class="invoice-input"></div>
      <div class="pay_button"></div>
      <div class="pay-status" style="text-align:center; font-size: 0.9em; margin-top: 10px; min-height: 20px;"></div>
    </div>
    <div class="confirmation-container hidden"></div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const button_container = shadow.querySelector('.pay_button')
  const invoice_input_component = shadow.querySelector('.invoice-input')
  const confirmation_container = shadow.querySelector('.confirmation-container')
  const status_el = shadow.querySelector('.pay-status')

  const subs = await sdb.watch(onbatch)

  const button_component = await pay_button(subs[0])
  const invoice_component = await invoice_input(subs[1])

  button_container.append(button_component)
  invoice_input_component.append(invoice_component)

  let invoice_mounted = false

  const closeBtn = shadow.querySelector('.x-icon')
  if (closeBtn) {
    closeBtn.onclick = () => {
      if (onCloseFn) onCloseFn()
      const dropdown = el.parentNode
      if (dropdown) {
        dropdown.classList.add('hidden')
      }
    }
  }

  let current_invoice = ''
  let confirm_el = null

  button_container.addEventListener('click', async () => {
    const inv = invoice_component.getValue ? invoice_component.getValue().trim() : ''
    if (!inv) {
      status_el.textContent = '❌ Please enter an invoice'
      status_el.style.color = 'red'
      return
    }

    current_invoice = inv
    status_el.textContent = '⏳ Preparing route and estimating fee...'
    status_el.style.color = '#555'

    if (onDecode) onDecode(inv)
  })

  el.onDecoded = async function (data) {
    if (data && data.error) {
      status_el.textContent = '❌ ' + (data.error || 'Failed to decode invoice')
      status_el.style.color = 'red'
      return
    }

    status_el.textContent = ''
    confirmation_container.classList.remove('hidden')

    if (!invoice_mounted) {
      confirm_el = await pay_invoice_confirmation(subs[2], {
        onClose: () => confirmation_container.classList.add('hidden'),
        onConfirm: () => {
          status_el.textContent = '⏳ Paying invoice...'
          status_el.style.color = '#555'
          if (onPay) onPay(current_invoice)
        }
      })
      confirmation_container.append(confirm_el)
      invoice_mounted = true
    }

    if (confirm_el && typeof confirm_el.updateInvoiceData === 'function') {
      confirm_el.updateInvoiceData(data)
    }
  }

  el.onPaid = function (data) {
    if (data && data.error) {
      status_el.textContent = '❌ ' + (data.error || 'Payment failed')
      status_el.style.color = 'red'
      confirmation_container.classList.add('hidden')
    } else {
      status_el.textContent = '✅ Payment Successful!'
      status_el.style.color = 'green'
      if (confirm_el && typeof confirm_el.updatePaymentData === 'function') {
        confirm_el.updatePaymentData(data)
      }
      confirmation_container.classList.remove('hidden')
    }
  }

  el.reset = function () {
    // Clear invoice input using the public clear() method on input_field
    if (invoice_component && typeof invoice_component.clear === 'function') {
      invoice_component.clear()
    }
    status_el.textContent = ''
    status_el.style.color = ''
    confirmation_container.classList.add('hidden')
    current_invoice = ''
  }

  return el


  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data

    const lightning_icon = shadow.querySelector('.lightning-icon')
    const x_icon = shadow.querySelector('.x-icon')

    lightning_icon.innerHTML = dricons[0]
    x_icon.innerHTML = dricons[1]
  }

  async function ondata(data) { }
}

function fallback_module() {
  return {
    api,
    _: {
      'button': { $: '' },
      'input_field': { $: '' },
      'pay_invoice_confirmation': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const button = {
      mapping: {
        style: 'style',
        data: 'data',
      },
      0: {
        label: 'Pay Invoice'
      }
    }

    const input_field = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      1: {
        header: 'Lightning Invoice',
        placeholder: 'Tap to paste your lightning invoice',
        address: 'lnbc1u1p0exampleinvoicehere1234567890'  // demo value
      }
    }

    const pay_invoice_confirmation = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      2: {
        value: [
          { label: "Amount", value: "0.0030 BTC", convert: true },
          { label: "Fee", value: "0.0001 BTC", convert: true },
          { label: "Recipient Address", value: "7RwmbHfn...455p" },
          { label: "Processing time", value: "< 5 minutes" },
          { label: "Total (inc. fee)", value: "0.0031 BTC ", icon: "lightning.svg", convert: true }
        ]
      },
    }

    return {
      drive: {
        'icons/': {
          'lightning.svg': {
            '$ref': 'lightning.svg'
          },
          'x.svg': {
            '$ref': 'x.svg'
          },
        },
        'style/': {
          'pay_invoice.css': {
            '$ref': 'pay_invoice.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        button,
        input_field,
        pay_invoice_confirmation
      }
    }
  }
}
